import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p56_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matmul_sigmoid_sum_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias_opt);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_sigmoid_sum_cuda", &matmul_sigmoid_sum_cuda,
          "Fused matmul + sigmoid + row-sum (CUDA float32)",
          py::arg("x"), py::arg("weight"), py::arg("bias"));
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused matmul + sigmoid + row-sum kernel.
// Each block handles one batch row. Threads stride across hidden_size columns.
// Dot product is computed in tiles over input_size, bias added, sigmoid applied,
// and result accumulated into a per-thread register sum before block reduction.

#define TILE_K 128

__global__ void matmul_sigmoid_sum_kernel(
    const float* __restrict__ x,       // (M, K)
    const float* __restrict__ weight,  // (N, K)  -- nn.Linear stores (out, in)
    const float* __restrict__ bias,    // (N,) or nullptr
    float* __restrict__ out,           // (M, 1)
    int M, int N, int K)
{
    int row = blockIdx.x;  // batch row
    if (row >= M) return;

    const float* x_row = x + row * K;

    // Each thread accumulates a partial row-sum over a stride of N columns.
    float row_accum = 0.0f;

    for (int col = threadIdx.x; col < N; col += blockDim.x) {
        const float* w_row = weight + col * K;  // weight[col, :]
        float dot = 0.0f;

        // Tile over K to allow compiler to unroll and keep registers tight.
        int k = 0;
        for (; k <= K - 4; k += 4) {
            dot += x_row[k]     * w_row[k];
            dot += x_row[k + 1] * w_row[k + 1];
            dot += x_row[k + 2] * w_row[k + 2];
            dot += x_row[k + 3] * w_row[k + 3];
        }
        for (; k < K; ++k) {
            dot += x_row[k] * w_row[k];
        }

        if (bias != nullptr) dot += bias[col];

        // Sigmoid and immediate accumulation -- never write intermediate to global.
        row_accum += 1.0f / (1.0f + __expf(-dot));
    }

    // Warp-level reduction using shuffle.
    unsigned int mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        row_accum += __shfl_down_sync(mask, row_accum, offset);

    // One warp per block approach: collect partial sums from each warp.
    extern __shared__ float smem[];  // one float per warp
    int lane   = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) smem[warp_id] = row_accum;
    __syncthreads();

    // Final reduction by first warp.
    int num_warps = (blockDim.x + 31) >> 5;
    float val = (threadIdx.x < num_warps) ? smem[threadIdx.x] : 0.0f;
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(mask, val, offset);

    if (threadIdx.x == 0) out[row] = val;
}

torch::Tensor matmul_sigmoid_sum_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias_opt)
{
    TORCH_CHECK(x.is_cuda(),      "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 2,     "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int M = x_c.size(0);
    int K = x_c.size(1);
    int N = w_c.size(0);
    TORCH_CHECK(w_c.size(1) == K, "weight inner dim must match x inner dim");

    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias_opt.defined() && bias_opt.numel() > 0) {
        bias_c = bias_opt.contiguous();
        TORCH_CHECK(bias_c.is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias_c.scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias_c.numel() == N, "bias length must equal hidden_size");
        bias_ptr = bias_c.data_ptr<float>();
    }

    auto out = torch::empty({M, 1}, x_c.options());

    // 256 threads per block; shared memory for up to 8 warps.
    int threads = 256;
    int num_warps = threads / 32;
    size_t smem_bytes = num_warps * sizeof(float);

    matmul_sigmoid_sum_kernel<<<M, threads, smem_bytes>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        M, N, K);

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a matrix multiplication, applies sigmoid, and sums the result.
        """
    def __init__(self, input_size, hidden_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.linear = nn.Linear(input_size, hidden_size)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, input_size).

                Returns:
                    Output tensor of shape (batch_size, 1).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and self.linear.weight.dtype == torch.float32:
            bias_tensor = self.linear.bias if self.linear.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)
            x = _stark_get_extension().matmul_sigmoid_sum_cuda(x, self.linear.weight, bias_tensor)
            return x
        else:
            x = self.linear(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = torch.sigmoid(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = torch.sum(x, dim=1, keepdim=True)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

