CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

// Singleton cuBLAS handle
static cublasHandle_t g_cublas_handle = nullptr;

static cublasHandle_t get_cublas_handle() {
    if (g_cublas_handle == nullptr) {
        cublasCreate(&g_cublas_handle);
        // Enable TF32 on Ampere for faster FP32 GEMM
        cublasSetMathMode(g_cublas_handle, CUBLAS_DEFAULT_MATH);
    }
    return g_cublas_handle;
}

// Fused sigmoid + row-sum epilogue kernel.
// Input:  gemm_out (M, N) float32
// Bias:   (N,) float32 or nullptr
// Output: out (M,) float32  -- one scalar per batch row
// Each block handles one row; threads stride across N with float4 loads.
__global__ void sigmoid_sum_kernel(
    const float* __restrict__ gemm_out,  // (M, N)
    const float* __restrict__ bias,      // (N,) or nullptr
    float* __restrict__ out,             // (M,)
    int M, int N)
{
    int row = blockIdx.x;
    if (row >= M) return;

    const float* row_ptr = gemm_out + (long long)row * N;

    float accum = 0.0f;

    // Vectorized path: process 4 floats at a time
    int n4 = N / 4;
    const float4* row_ptr4 = reinterpret_cast<const float4*>(row_ptr);

    if (bias != nullptr) {
        const float4* bias4 = reinterpret_cast<const float4*>(bias);
        for (int i = threadIdx.x; i < n4; i += blockDim.x) {
            float4 v = row_ptr4[i];
            float4 b = bias4[i];
            accum += 1.0f / (1.0f + __expf(-(v.x + b.x)));
            accum += 1.0f / (1.0f + __expf(-(v.y + b.y)));
            accum += 1.0f / (1.0f + __expf(-(v.z + b.z)));
            accum += 1.0f / (1.0f + __expf(-(v.w + b.w)));
        }
        // Remainder
        for (int i = n4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
            accum += 1.0f / (1.0f + __expf(-(row_ptr[i] + bias[i])));
        }
    } else {
        for (int i = threadIdx.x; i < n4; i += blockDim.x) {
            float4 v = row_ptr4[i];
            accum += 1.0f / (1.0f + __expf(-v.x));
            accum += 1.0f / (1.0f + __expf(-v.y));
            accum += 1.0f / (1.0f + __expf(-v.z));
            accum += 1.0f / (1.0f + __expf(-v.w));
        }
        for (int i = n4 * 4 + threadIdx.x; i < N; i += blockDim.x) {
            accum += 1.0f / (1.0f + __expf(-row_ptr[i]));
        }
    }

    // Warp-level reduction
    unsigned int mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        accum += __shfl_down_sync(mask, accum, offset);

    // Collect warp sums in shared memory
    extern __shared__ float smem[];
    int lane    = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) smem[warp_id] = accum;
    __syncthreads();

    int num_warps = (blockDim.x + 31) >> 5;
    float val = (threadIdx.x < num_warps) ? smem[threadIdx.x] : 0.0f;
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(mask, val, offset);

    if (threadIdx.x == 0) out[row] = val;
}

torch::Tensor matmul_sigmoid_sum_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias_opt)
{
    TORCH_CHECK(x.is_cuda(),       "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(),  "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 2,      "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(x.scalar_type()      == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int M = (int)x_c.size(0);
    int K = (int)x_c.size(1);
    int N = (int)w_c.size(0);  // hidden_size
    TORCH_CHECK(w_c.size(1) == K, "weight inner dim must match x inner dim");

    // Allocate temporary GEMM output (M, N) -- no bias yet, added in epilogue
    auto gemm_out = torch::empty({M, N}, x_c.options());

    // cuBLAS SGEMM: C = A * B^T
    // PyTorch tensors are row-major. cuBLAS is column-major.
    // We want: gemm_out(M,N) = x(M,K) * weight^T(K,N)
    // In column-major terms: C(N,M) = weight(N,K) * x^T(K,M)
    // So: sgemm(N, M, K, alpha, weight_ptr, N, x_ptr, K, beta, gemm_out_ptr, N)
    // with transa=CUBLAS_OP_T (weight), transb=CUBLAS_OP_N (x)
    // Actually using: C = op(B) * op(A), where op(A)=weight (N,K), op(B)=x^T
    // Standard row-major trick: C_row = A_row * B_row^T
    //   => in col-major: C_col^T = (A_row * B_row^T)^T = B_row * A_row^T
    // cublasSgemm args: (handle, transa, transb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc)
    // where result is C(m,n) = op(A)(m,k) * op(B)(k,n)
    // We want gemm_out(M,N) = x(M,K) * weight^T(K,N)
    // In col-major: treat as gemm_out^T(N,M) = weight(N,K) * x^T(K,M)
    // => sgemm(N, M, K, alpha=1, weight_ptr, lda=N, x_ptr, ldb=K, beta=0, out_ptr, ldc=N)
    // with transa=CUBLAS_OP_N, transb=CUBLAS_OP_T
    // Wait -- let's be precise:
    //   cuBLAS col-major: C(ldc, n_cols) = op(A) * op(B)
    //   We want in row-major: OUT[M][N] = X[M][K] * W^T[K][N]
    //   Reinterpret as col-major: OUT^T[N][M] = W[N][K] * X^T[K][M]
    //   => sgemm(CUBLAS_OP_N, CUBLAS_OP_T, N, M, K, 1.0, W, N, X, K, 0.0, OUT, N)
    cublasHandle_t handle = get_cublas_handle();
    float alpha = 1.0f, beta = 0.0f;
    cublasSgemm(handle,
                CUBLAS_OP_N, CUBLAS_OP_T,
                N, M, K,
                &alpha,
                w_c.data_ptr<float>(), N,
                x_c.data_ptr<float>(), K,
                &beta,
                gemm_out.data_ptr<float>(), N);

    // Epilogue: add bias, apply sigmoid, reduce each row to scalar
    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias_opt.defined() && bias_opt.numel() > 0) {
        bias_c = bias_opt.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }

    // Output: (M, 1)
    auto out_flat = torch::empty({M}, x_c.options());

    int threads = 512;
    int num_warps = threads / 32;
    size_t smem_bytes = num_warps * sizeof(float);
    sigmoid_sum_kernel<<<M, threads, smem_bytes>>>(
        gemm_out.data_ptr<float>(),
        bias_ptr,
        out_flat.data_ptr<float>(),
        M, N);

    return out_flat.unsqueeze(1);  // (M, 1)
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a matrix multiplication, applies sigmoid, and sums the result.
        """
    def __init__(self, input_size, hidden_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.linear = nn.Linear(input_size, hidden_size)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, input_size).

                Returns:
                    Output tensor of shape (batch_size, 1).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and self.linear.weight.dtype == torch.float32:
            bias_tensor = self.linear.bias if self.linear.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)
            return _stark_get_extension().matmul_sigmoid_sum_cuda(x, self.linear.weight, bias_tensor)
        x = self.linear(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = torch.sigmoid(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = torch.sum(x, dim=1, keepdim=True)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

